//! The Huedra settings window, run as its own process (`huedra settings`).
//! Feature doc: `docs/features/08-settings-window.md`.
//!
//! The window exists only on Windows; on other platforms this crate is empty
//! so the workspace still builds and tests on Linux.

#![deny(unsafe_code)]

#[cfg(windows)]
mod app;
#[cfg(windows)]
mod flyout;
#[cfg(windows)]
mod icons;
#[cfg(windows)]
mod lookups;
#[cfg(all(windows, feature = "sample"))]
mod sample;

/// Code generated by `slint-build` from `ui/*.slint`.
#[cfg(windows)]
#[allow(
    unsafe_code,
    missing_docs,
    clippy::all,
    clippy::pedantic,
    clippy::restriction,
    reason = "generated by slint-build; not written by hand"
)]
mod ui {
    slint::include_modules!();
}

#[cfg(windows)]
pub use app::{Page, run};
#[cfg(windows)]
pub use flyout::{TITLE as FLYOUT_TITLE, is_open as flyout_open, run as run_flyout};
